def clip_polygon(poly,axis,bound,keep_greater):
    result=[]
    for start,end in zip(poly,poly[1:]+poly[:1]):
        ds=(start[axis]-bound)*(1 if keep_greater else -1); de=(end[axis]-bound)*(1 if keep_greater else -1)
        if ds>=0: result.append(start)
        if (ds<0 and de>0) or (ds>0 and de<0):
            ratio=ds/(ds-de); result.append(tuple(a+ratio*(b-a) for a,b in zip(start,end)))
    return result
def area2(poly):
